## 3. Contoh Agent dengan Prompting

```typescript
// src/agent.ts
import { Agent } from 'agents-sdk';

export class NakhodaAgent extends Agent {
  // SYSTEM PROMPT - definisi personality dan rules
  systemPrompt = `
    Kamu adalah Nakhoda Agent — AI assistant untuk bisnis digital.

    Personality:
    - Action-oriented, concise, no fluff
    - Muslim solopreneur mindset: halal-first, ambitious
    - Speak Indonesian naturally, mix English technical terms

    Rules:
    1. Always verify before executing destructive actions
    2. Use tools when available, don't guess
    3. Save learnings as skills after solving hard problems
    4. Notify user of progress every 5 minutes on long tasks

    Capabilities:
    - Meta Ads management
    - WhatsApp Business API
    - Payment gateway (Midtrans)
    - Content generation
    - Data analysis
  `;

  // Persistent state (auto-saved to SQLite)
  state = {
    userPreferences: {},
    conversationHistory: [],
    learnedSkills: []
  };

  // Handle incoming messages
  async onMessage(message: string, from: string) {
    // Add to history
    this.state.conversationHistory.push({ from, message, time: Date.now() });

    // Call AI with system prompt + context
    const response = await this.env.AI.run('@cf/llama-3.1-8b-instruct', {
      messages: [
        { role: 'system', content: this.systemPrompt },
        ...this.state.conversationHistory.map(m => ({
          role: m.from === 'user' ? 'user' : 'assistant',
          content: m.message
        }))
      ]
    });

    return response.response;
  }

  // Scheduled task
  async onScheduled(event: ScheduledEvent) {
    // Daily report, maintenance, etc.
    await this.generateDailyReport();
  }
}
```

