## 7. Integration dengan MCP (Model Context Protocol)

Cloudflare Agents bisa connect ke MCP servers untuk extended capabilities:

```typescript
import { MCPClient } from 'agents-sdk/tools/mcp';

export class NakhodaAgent extends Agent {
  mcpClient: MCPClient;

  async init() {
    // Connect to Cloudflare MCP servers
    this.mcpClient = new MCPClient({
      servers: [
        { url: 'https://bindings.mcp.cloudflare.com/mcp' },  // Workers bindings
        { url: 'https://observability.mcp.cloudflare.com/mcp' },  // Logs
        { url: 'https://ai-gateway.mcp.cloudflare.com/mcp' }  // AI analytics
      ]
    });
  }

  async onMessage(message: string) {
    // Use MCP tools
    const workers = await this.mcpClient.call('list_workers');
    const logs = await this.mcpClient.call('get_logs', { limit: 10 });

    // Process with AI
    return await this.env.AI.run('@cf/llama-3.1-8b-instruct', {
      prompt: `Analyze these workers: ${JSON.stringify(workers)}`
    });
  }
}
```

